#include <stdio.h>

typedef struct { int no; char name[8]; } Student;

int main(void)
{
    Student L[4] = { {1001,"Ann"}, {1002,"Bob"}, {1003,"Cid"}, {1004,"Dan"} };
    int n = 4, i;

    printf("n = %d 的线性表（位序从 1 开始）\n", n);
    for (i = 1; i <= n; i++) {
        printf("位序 %d : %d %-4s", i, L[i-1].no, L[i-1].name);
        if (i == 1)      printf("[表头，无直接前驱]");
        else if (i == n) printf("[表尾，无直接后继]");
        else             printf("前驱=位序%d 后继=位序%d", i-1, i+1);
        printf("\n");
    }
    printf("下标 = 位序 - 1：位序 3 对应 L[%d]\n", 3 - 1);
    return 0;
}

#include <stdio.h>

#define MAXSIZE 10
typedef int ElemType;
typedef struct { ElemType data[MAXSIZE]; int length; } SqList;

/* cur 是 L 的元素且不是第一个时，返回其前驱 */
int PriorElem(const SqList *L, ElemType cur, ElemType *pre)
{
    int i;
    for (i = 1; i < L->length; i++)
        if (L->data[i] == cur) { *pre = L->data[i-1]; return 1; }
    return 0;
}

/* cur 是 L 的元素且不是最后一个时，返回其后继 */
int NextElem(const SqList *L, ElemType cur, ElemType *next)
{
    int i;
    for (i = 0; i < L->length - 1; i++)
        if (L->data[i] == cur) { *next = L->data[i+1]; return 1; }
    return 0;
}

int main(void)
{
    SqList L = { {5, 8, 13, 21, 34}, 5 };
    ElemType v = 0;
    if (PriorElem(&L, 13, &v)) printf("13 的前驱 = %d\n", v);
    if (NextElem(&L, 13, &v))  printf("13 的后继 = %d\n", v);
    printf("表头 5  有前驱? %d\n", PriorElem(&L, 5, &v));
    printf("表尾 34 有后继? %d\n", NextElem(&L, 34, &v));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef int ElemType;
typedef struct {
    ElemType *elem;      /* 动态分配的空间基址 */
    int       length;    /* 当前长度 */
    int       listsize;  /* 当前容量 */
} SqList;

int InitList(SqList *L, int cap)
{
    L->elem = (ElemType *)malloc((size_t)cap * sizeof(ElemType));
    if (L->elem == NULL) return 0;   /* 存储分配失败 */
    L->length = 0;
    L->listsize = cap;
    return 1;
}

int ListInsert(SqList *L, int i, ElemType e)
{
    int k;
    if (i < 1 || i > L->length + 1) return 0;   /* 位序非法 */
    if (L->length >= L->listsize) return 0;     /* 表满 */
    for (k = L->length - 1; k >= i - 1; k--)
        L->elem[k + 1] = L->elem[k];
    L->elem[i - 1] = e;
    L->length++;
    return 1;
}

int ListDelete(SqList *L, int i, ElemType *e)
{
    int k;
    if (i < 1 || i > L->length) return 0;
    *e = L->elem[i - 1];
    for (k = i; k < L->length; k++)
        L->elem[k - 1] = L->elem[k];
    L->length--;
    return 1;
}

void DestroyList(SqList *L)
{
    free(L->elem);
    L->elem = NULL;
    L->length = L->listsize = 0;
}

int main(void)
{
    SqList L;
    ElemType e = 0;
    int i;
    if (!InitList(&L, 8)) { printf("malloc failed\n"); return 1; }
    for (i = 1; i <= 5; i++) ListInsert(&L, i, i * i);
    printf("elem:");
    for (i = 1; i <= L.length; i++) printf(" %d", L.elem[i-1]);
    printf("\nlength=%d listsize=%d\n", L.length, L.listsize);
    ListInsert(&L, 2, 100);
    ListDelete(&L, 4, &e);
    printf("insert@2 then delete@4 (deleted=%d):", e);
    for (i = 1; i <= L.length; i++) printf(" %d", L.elem[i-1]);
    printf("\n");
    DestroyList(&L);
    printf("destroyed, elem == NULL ? %d\n", L.elem == NULL);
    return 0;
}

#include <stdio.h>

#define NMAX 8

int main(void)
{
    int i, n;
    printf("n   插入平均搬移(=n/2)   删除平均搬移(=(n-1)/2)\n");
    for (n = 1; n <= NMAX; n++) {
        int ins = 0, del = 0;
        for (i = 1; i <= n + 1; i++) ins += (n - i + 1); /* n+1 个可插位置 */
        for (i = 1; i <= n;     i++) del += (n - i);     /* n 个可删位置 */
        printf("%-3d %-20.3f %.3f\n", n,
               (double)ins / (n + 1), (double)del / n);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef int ElemType;
typedef struct LNode {
    ElemType       data;
    struct LNode  *next;
} LNode, *LinkList;

int CreateTail(LinkList *L, const ElemType a[], int n)
{
    LNode *tail, *s;
    int i;
    *L = (LinkList)malloc(sizeof(LNode));   /* 头结点 */
    if (*L == NULL) return 0;
    (*L)->next = NULL;                      /* 空表 */
    tail = *L;
    for (i = 0; i < n; i++) {
        s = (LNode *)malloc(sizeof(LNode));
        if (s == NULL) return 0;
        s->data = a[i];
        s->next = NULL;
        tail->next = s;                     /* 挂到表尾 */
        tail = s;                           /* 尾指针后移 */
    }
    return 1;
}

void ListTraverse(LinkList L)
{
    LNode *p = L->next;                     /* 跳过头结点 */
    printf("head");
    while (p != NULL) { printf(" -> %d", p->data); p = p->next; }
    printf(" -> NULL\n");
}

void DestroyList(LinkList *L)
{
    LNode *p = *L, *q;
    while (p != NULL) { q = p->next; free(p); p = q; }
    *L = NULL;
}

int main(void)
{
    LinkList L = NULL;
    ElemType a[6] = {11, 22, 33, 44, 55, 66};
    if (!CreateTail(&L, a, 6)) { printf("malloc failed\n"); return 1; }
    ListTraverse(L);
    printf("表空? %d\n", L->next == NULL);
    DestroyList(&L);
    printf("destroyed -> %s\n", L == NULL ? "NULL" : "?");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef char ElemType;
typedef struct LNode { ElemType data; struct LNode *next; } LNode, *LinkList;

/* 返回第 i 个结点的指针，头结点算第 0 个；越界返回 NULL */
LNode *GetElemP(LinkList L, int i)
{
    LNode *p = L;
    int j = 0;
    while (p != NULL && j < i) { p = p->next; j++; }
    if (i < 0 || j > i) return NULL;
    return p;
}

int ListInsert(LinkList L, int i, ElemType e)
{
    LNode *p = GetElemP(L, i - 1), *s;   /* 找第 i-1 个结点 */
    if (p == NULL) return 0;
    s = (LNode *)malloc(sizeof(LNode));
    if (s == NULL) return 0;
    s->data = e;
    s->next = p->next;    /* ① 先接 */
    p->next = s;          /* ② 后断 */
    return 1;
}

int ListDelete(LinkList L, int i, ElemType *e)
{
    LNode *p = GetElemP(L, i - 1), *q;
    if (p == NULL || p->next == NULL) return 0;
    q = p->next;
    *e = q->data;
    p->next = q->next;
    free(q);
    return 1;
}

int main(void)
{
    LNode head, *p, *q;
    LinkList L = &head;
    ElemType e = 0;
    int i;

    head.data = '#'; head.next = NULL;          /* 头结点 */
    for (i = 1; i <= 5; i++) ListInsert(L, i, (ElemType)('A' + i - 1));

    printf("create      :");
    for (p = L->next; p != NULL; p = p->next) printf(" %c", p->data);
    ListInsert(L, 3, 'X');
    printf("\ninsert X @3 :");
    for (p = L->next; p != NULL; p = p->next) printf(" %c", p->data);
    ListDelete(L, 2, &e);
    printf("\ndelete @2=%c :", e);
    for (p = L->next; p != NULL; p = p->next) printf(" %c", p->data);
    printf("\n第3个元素 = %c\n", GetElemP(L, 3)->data);

    p = L->next;                                /* 释放所有数据结点 */
    while (p != NULL) { q = p->next; free(p); p = q; }
    L->next = NULL;
    printf("all data nodes freed, 表空? %d\n", L->next == NULL);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef int ElemType;
typedef struct DuLNode {
    ElemType        data;
    struct DuLNode *prior;
    struct DuLNode *next;
} DuLNode, *DuLinkList;

int InitDuList(DuLinkList *L)
{
    *L = (DuLinkList)malloc(sizeof(DuLNode));
    if (*L == NULL) return 0;
    (*L)->prior = (*L)->next = *L;   /* 空的双向循环链表：头结点自环 */
    return 1;
}

int InsertAfter(DuLinkList p, ElemType e)   /* 在 p 之后插入 */
{
    DuLNode *s = (DuLNode *)malloc(sizeof(DuLNode));
    if (s == NULL) return 0;
    s->data = e;
    s->prior = p;
    s->next  = p->next;
    p->next->prior = s;      /* 必须先改后继的 prior */
    p->next = s;             /* 再改前驱的 next */
    return 1;
}

int DeleteNode(DuLinkList p)                /* p 由调用方保证不是头结点 */
{
    if (p == NULL) return 0;
    p->prior->next = p->next;
    p->next->prior = p->prior;
    free(p);
    return 1;
}

int main(void)
{
    DuLinkList L = NULL, p;
    DuLNode *q;
    int i;
    if (!InitDuList(&L)) { printf("malloc failed\n"); return 1; }

    p = L;
    for (i = 1; i <= 5; i++) { InsertAfter(p, i * 10); p = p->next; }

    printf("空表判断 L->next==L ? %d\n", L->next == L);
    printf("正向:");
    for (p = L->next; p != L; p = p->next)  printf(" %d", p->data);
    printf("\n反向:");
    for (p = L->prior; p != L; p = p->prior) printf(" %d", p->data);
    printf("\n");

    p = L->next->next->next;   /* 第 3 个数据结点 */
    printf("待删除 = %d\n", p->data);
    DeleteNode(p);
    printf("删后正向:");
    for (p = L->next; p != L; p = p->next)  printf(" %d", p->data);
    printf("\n删后反向:");
    for (p = L->prior; p != L; p = p->prior) printf(" %d", p->data);
    printf("\n");

    p = L->next;               /* 销毁：沿 next 走一圈回到头结点 */
    while (p != L) { q = p->next; free(p); p = q; }
    free(L);
    printf("freed\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct CNode { int no; struct CNode *next; } CNode;

int main(void)
{
    int n = 8, m = 3, i;
    CNode *L, *p, *prev, *s, *q;

    L = (CNode *)malloc(sizeof(CNode));
    if (L == NULL) return 1;
    L->no = 1; L->next = L;        /* 1 号自己成环 */
    p = L;
    for (i = 2; i <= n; i++) {     /* 尾插建环 */
        s = (CNode *)malloc(sizeof(CNode));
        if (s == NULL) return 1;
        s->no = i; s->next = L;
        p->next = s; p = s;
    }

    printf("n=%d m=%d 出列顺序:", n, m);
    prev = p;                      /* prev 指向尾结点 */
    p = L;                         /* p 指向 1 号 */
    while (p->next != p) {         /* 环中不止一个结点 */
        for (i = 1; i < m; i++) { prev = p; p = p->next; }
        printf(" %d", p->no);
        prev->next = p->next;      /* 摘掉 p */
        q = p; p = p->next; free(q);
    }
    printf(" %d(最后)\n", p->no);
    free(p);
    return 0;
}
